objective.code:
def pinch_objective(scene: Component) -> dict[str, Loss]:
    """Load the thumb and the fingers against each other, the native
    capture's own thumb, finger and opposition support residuals."""
    support = cast(PickupScene, scene).support
    return {name: support[name] for name in ("thumb", "fingers", "opposition")}

effect.code:
def pinched(scene: Component) -> dict[str, Loss]:
    """The pinch is secured: thumb and two fingers carry half the weight each
    (the native capture's support residuals), with opposed normals."""
    support = cast(PickupScene, scene).support
    return {
        name: support[name]
        for name in ("thumb", "fingers", "opposition", "finger0", "finger1")
    }

